### Step 7: Create server-side ShipmentService

Create `ShipmentTracker/Services/ShipmentService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        var s = await db.Shipments.FindAsync(id);
        return s is null ? null : MapToDto(s);
    }

    public async Task<TrackingResult> TrackShipmentAsync(string trackingNumber)
    {
        var s = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        if (s is null)
            return new TrackingResult { Found = false, Message = "No shipment found with that tracking number." };
        return new TrackingResult { Found = true, Shipment = MapToDto(s) };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var entity = new Shipment
        {
            TrackingNumber = dto.TrackingNumber,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = dto.Status,
            CustomerEmail = dto.CustomerEmail,
            ShippedDate = dto.ShippedDate,
            EstimatedDelivery = dto.EstimatedDelivery,
            CarrierName = dto.CarrierName,
            Notes = dto.Notes
        };
        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return MapToDto(entity);
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatusUpdate update)
    {
        var entity = await db.Shipments.FindAsync(id) 
            ?? throw new KeyNotFoundException($"Shipment {id} not found.");
        entity.Status = update.Status;
        entity.Notes = update.Notes;
        if (update.Status == "Delivered")
            entity.ActualDelivery = DateTime.UtcNow;
        await db.SaveChangesAsync();
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        CustomerEmail = s.CustomerEmail,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        CarrierName = s.CarrierName,
        Notes = s.Notes
    };
}
```

