    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string statusFilter = "";
    private bool showCreateForm;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(7), ShippedDate = DateTime.Now, Status = "Pending" };
    private bool isSaving;
    private string? createError;
    private int? editingId;
    private string editStatus = "";
    private string editNotes = "";

    private IEnumerable<ShipmentDto> FilteredShipments => (shipments ?? [])
        .Where(s => (string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter)
            && (string.IsNullOrEmpty(filterText) 
                || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase)));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task CreateShipment()
    {
        isSaving = true;
        createError = null;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            shipments = await ShipmentService.GetAllShipmentsAsync();
            showCreateForm = false;
            newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(7), ShippedDate = DateTime.Now, Status = "Pending" };
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void StartEdit(ShipmentDto s)
    {
        editingId = s.Id;
        editStatus = s.Status;
        editNotes = s.Notes;
    }

    private void CancelEdit() => editingId = null;

    private async Task SaveStatus(int id)
    {
        await ShipmentService.UpdateStatusAsync(id, new ShipmentStatusUpdate { Status = editStatus, Notes = editNotes });
        shipments = await ShipmentService.GetAllShipmentsAsync();
        editingId = null;
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Delayed" => "bg-danger",
        "Pending" => "bg-secondary",
        _ => "bg-info"
    };
}
