arguments.new_str:
@page "/"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>ShipmentTracker — Home</PageTitle>

<h1>Shipment Tracker</h1>
<p class="lead">Track your shipment in real time.</p>

<div class="row mb-4">
    <div class="col-md-8">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-20260001)"
                   @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Track
            </button>
        </div>
    </div>
</div>

@if (result is not null)
{
    @if (result.Found && result.Shipment is not null)
    {
        var s = result.Shipment;
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>@s.TrackingNumber</strong>
                <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <p><strong>From:</strong> @s.Origin</p>
                        <p><strong>To:</strong> @s.Destination</p>
                        <p><strong>Carrier:</strong> @s.CarrierName</p>
                    </div>
                    <div class="col-md-6">
                        <p><strong>Shipped:</strong> @s.ShippedDate.ToString("MMM dd, yyyy")</p>
                        <p><strong>Estimated Delivery:</strong> @s.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                        @if (s.ActualDelivery.HasValue)
                        {
                            <p><strong>Delivered:</strong> @s.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
                        }
                    </div>
                </div>
                @if (!string.IsNullOrWhiteSpace(s.Notes))
                {
                    <p class="text-muted mt-2"><em>@s.Notes</em></p>
                }
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">@result.Message</div>
    }
}

@code {
    private string trackingNumber = "";
    private TrackingResult? result;
    private bool isLoading;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        result = null;
        try
        {
            result = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Delayed" => "bg-danger",
        "Pending" => "bg-secondary",
        _ => "bg-info"
    };
}

using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>()
            .HasIndex(s => s.TrackingNumber)
            .IsUnique();

        builder.Entity<Shipment>().HasData(
