@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments — Dispatcher View</PageTitle>

<h1>Shipments</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination or tracking #..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            <option value="Pending">Pending</option>
            <option value="In Transit">In Transit</option>
            <option value="Delivered">Delivered</option>
            <option value="Delayed">Delayed</option>
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-success" @onclick="() => showCreateForm = !showCreateForm">
            @(showCreateForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5>Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-4">
                    <input class="form-control" placeholder="Tracking Number" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Carrier Name" @bind="newShipment.CarrierName" />
                </div>
                <div class="col-md-4">
                    <label class="form-label mb-0">Est. Delivery</label>
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-12">
                    <input class="form-control" placeholder="Notes" @bind="newShipment.Notes" />
                </div>
                <div class="col-12">
                    <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isSaving">
                        @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Create
                    </button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(createError))
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <div class="alert alert-info">No shipments match your filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Carrier</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <select class="form-select form-select-sm" @bind="editStatus">
                                    <option value="Pending">Pending</option>
                                    <option value="In Transit">In Transit</option>
                                    <option value="Delivered">Delivered</option>
                                    <option value="Delayed">Delayed</option>
                                </select>
                            }
                            else
                            {
                                <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                            }
                        </td>
                        <td>@s.CarrierName</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <button class="btn btn-sm btn-primary me-1" @onclick="() => SaveStatus(s.Id)">Save</button>
                                <button class="btn btn-sm btn-secondary" @onclick="CancelEdit">Cancel</button>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">Update</button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string statusFilter = "";
    private bool showCreateForm;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(7), ShippedDate = DateTime.Now, Status = "Pending" };
    private bool isSaving;
    private string? createError;
    private int? editingId;
    private string editStatus = "";
    private string editNotes = "";

    private IEnumerable<ShipmentDto> FilteredShipments => (shipments ?? [])
        .Where(s => (string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter)
            && (string.IsNullOrEmpty(filterText) 
                || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase)));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task CreateShipment()
    {
        isSaving = true;
        createError = null;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            shipments = await ShipmentService.GetAllShipmentsAsync();
            showCreateForm = false;
            newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(7), ShippedDate = DateTime.Now, Status = "Pending" };
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void StartEdit(ShipmentDto s)
    {
        editingId = s.Id;
        editStatus = s.Status;
        editNotes = s.Notes;
    }

    private void CancelEdit() => editingId = null;

    private async Task SaveStatus(int id)
    {
        await ShipmentService.UpdateStatusAsync(id, new ShipmentStatusUpdate { Status = editStatus, Notes = editNotes });
        shipments = await ShipmentService.GetAllShipmentsAsync();
        editingId = null;
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Delayed" => "bg-danger",
        "Pending" => "bg-secondary",
        _ => "bg-info"
    };
}
```

**Create `ShipmentTracker.Client/Pages/NotFound.razor`** — Already exists, keep it.

### Step 10: Update NavMenu

Edit `ShipmentTracker.Client/Layout/NavMenu.razor` — replace the nav items section. Remove Counter, Weather, Auth Required links. Add:
- Home (tracking) — available to all
- Shipments (dispatcher) — requires auth

Replace the nav section between `<nav class="nav flex-column">` and `</nav>` with:
```razor
        <div class="nav-item px-3">
            <NavLink class="nav-link" href="" Match="NavLinkMatch.All">
                <span class="bi bi-house-door-fill-nav-menu" aria-hidden="true"></span> Track Shipment
            </NavLink>
        </div>

        <AuthorizeView>
            <Authorized>
                <div class="nav-item px-3">
                    <NavLink class="nav-link" href="shipments">
                        <span class="bi bi-list-nested-nav-menu" aria-hidden="true"></span> Shipments
                    </NavLink>
                </div>
            </Authorized>
        </AuthorizeView>
```
Keep the existing AuthorizeView block for account management (login/logout/register/manage).

### Step 11: Add EF Core migration and update database

Run:
```bash
cd /tmp/sv-ed803021ff864357bb296a13f95242f1/ShipmentTracker/ShipmentTracker
dotnet ef migrations add AddShipments
dotnet ef database update
```

If `dotnet ef` is not available, install it first:
```bash
dotnet tool install --global dotnet-ef
```

### Step 12: Create AGENTS.md

Create `ShipmentTracker/AGENTS.md` using the auto-global template at `/tmp/sv-iso-d33388f73544451b9b327cd40fa4889c/create-blazor-project/assets/agents-md/auto-global.md`, replacing `{AppName}` with `ShipmentTracker`. Add an `## Authentication` section noting that ASP.NET Core Identity is configured and Identity pages under `Components/Account/` are always static SSR.

### Step 13: Build and verify

Run `dotnet build` on the solution to confirm everything compiles.

## IMPORTANT RULES
- All interactive components go in the `.Client` project
- Do NOT add @rendermode to any pages (global interactivity)
- The tracking endpoint (`/track/{trackingNumber}`) does NOT require auth — customers can track without logging in
- The shipments list/create/update endpoints require auth
- Delete Counter.razor, Weather.razor, Auth.razor from `.Client/Pages/`
- Keep the existing NotFound.razor

## Execute all these steps now. Create all the files, edit existing files, run migrations, and build.

